import{St as e,at as t,it as n,n as r,st as i,tt as a,vt as o}from"./chunks/framework.BPeR9Rpo.js";var s=JSON.parse(`{"title":"Lösungen","description":"","frontmatter":{"title":"Lösungen","covers":{"screens":["SCR-060","SCR-061"],"stories":["US-038","US-039"]}},"headers":[],"relativePath":"de/usage/solutions.md","filePath":"de/usage/solutions.md"}`),c={name:`de/usage/solutions.md`};function l(r,s,c,l,u,d){let f=e(`Screenshot`);return o(),n(`div`,null,[s[0]||=t(`<h1 id="losungen" tabindex="-1">Lösungen <a class="header-anchor" href="#losungen" aria-label="Permalink to “Lösungen”">​</a></h1><p>Eine Lösung (Solution) ist der Container eines Veränderungsvorhabens, etwa eines neuen Moduls, einer ersetzten Schnittstelle oder einer Plattformmigration. Ihre <strong>Architekturvision</strong> hält fest, was das Vorhaben erreichen will und was es umfasst, damit alle Beteiligten dasselbe Bild haben. Später enthält die Lösung auch die geplanten Änderungen an der Landschaft.</p><p>Um Lösungen zu sehen, brauchst du die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>). Zum Anlegen brauchst du <code>solution:write</code>: Die Rollen <code>solution-architect</code> und <code>enterprise-architect</code> haben sie (siehe <a href="./../administration/roles-and-permissions">Rollen und Berechtigungen</a>).</p><h2 id="eine-losung-anlegen" tabindex="-1">Eine Lösung anlegen <a class="header-anchor" href="#eine-losung-anlegen" aria-label="Permalink to “Eine Lösung anlegen”">​</a></h2><ol><li><p>Wähle in der Kopfzeile <em>Lösungen</em> und dann <em>Neue Lösung</em>.</p></li><li><p>Fülle den Dialog <em>Neue Lösung</em> aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht, bis 255 Zeichen; eindeutig in der Instanz, unabhängig von Gross- und Kleinschreibung und von Leerzeichen am Anfang und Ende</td></tr><tr><td>Architekturvision</td><td>optional, bis 2000 Zeichen: Ziel, Umfang und Begründung des Vorhabens. Zeilenumbrüche bleiben erhalten</td></tr></tbody></table></li></ol>`,5),i(f,{name:`solution-create`,alt:`Dialog Neue Lösung mit Name und Architekturvision`}),s[1]||=t(`<ol start="3"><li>Wähle <em>Lösung anlegen</em>. Die Seite der neuen Lösung öffnet sich.</li></ol><p>Ist der Name schon vergeben, sagt der Dialog das, zum Beispiel „Der Name &#39;ERP Extension Logistics&#39; ist bereits vergeben“; wähle einen anderen Namen. Ohne <code>solution:write</code> siehst du die Lösungen, aber nicht <em>Neue Lösung</em>.</p><p>Eine neue Lösung hat den Status <em>Entwurf</em>, und du bist verantwortlich für sie. Sie entsteht im <strong>Projektmodus</strong>: ohne Ausgangs- und Zielplateau. Der Plateaumodus folgt mit den Plateaus.</p><h2 id="losungen-ansehen" tabindex="-1">Lösungen ansehen <a class="header-anchor" href="#losungen-ansehen" aria-label="Permalink to “Lösungen ansehen”">​</a></h2><p>Die Seite <em>Lösungen</em> listet jede Lösung mit Status, verantwortlicher Person und Anlagedatum, nach Name sortiert:</p>`,5),i(f,{name:`solutions`,alt:`Liste der Lösungen`}),s[2]||=a(`p`,null,`Öffne eine Lösung, um ihre Architekturvision und ihre Ausgangslage zu sehen:`,-1),i(f,{name:`solution`,alt:`Seite einer Lösung mit verantwortlicher Person, Anlagezeit, Architekturvision und Ausgangslage`}),s[3]||=t(`<p>Lösungen lassen sich noch nicht ändern oder archivieren.</p><h2 id="ausgangslage" tabindex="-1">Ausgangslage <a class="header-anchor" href="#ausgangslage" aria-label="Permalink to “Ausgangslage”">​</a></h2><p>Der Bereich <em>Ausgangslage</em> (Baseline) einer Lösung zeigt die aktuelle IT-Landschaft, auf der das Vorhaben aufbaut: jede Entität, die heute im Katalog steht und nicht gelöscht ist, mit Name und Metatyp, nach Name sortiert. Verbindungen wie Datenflüsse erscheinen nicht. Die Ausgangslage wird beim Öffnen der Lösung gelesen und zeigt deshalb immer den Katalog, wie er jetzt ist.</p><ul><li><strong>Suche:</strong> Gib einen Teil des Namens ein, bis 255 Zeichen; Gross- und Kleinschreibung spielen keine Rolle.</li><li><strong>Filter:</strong> Wähle einen Metatyp, um nur seine Entitäten zu sehen.</li><li><strong>Seiten:</strong> Die Ausgangslage zeigt 50 Entitäten pro Seite.</li></ul><p>Enthält der Katalog noch keine Entitäten, steht im Bereich „Keine Entitäten in der aktuellen Landschaft – du kannst nur neue Entitäten anlegen“. Findet nur deine Suche oder dein Filter nichts, steht stattdessen das.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;ERP Extension Logistics&quot;, &quot;description&quot;: &quot;Goal: warehouse logistics in the ERP.&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># $SOLUTION ist die &quot;id&quot; einer Lösung aus der Liste</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/solutions/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SOLUTION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/landscape?q=erp&amp;pageSize=50&quot;</span></span></code></pre></div><p><code>POST /solutions</code> antwortet mit 201 und der Lösung, mit 422 und <code>name</code> bei einem leeren oder vergebenen Namen und mit 403 ohne <code>solution:write</code>. Jedes Anlegen wird im Audit-Log als <code>solution.created</code> festgehalten.</p><p><code>GET /solutions/{id}/landscape</code> liefert eine Seite der Ausgangslage mit der Gesamtzahl und, falls es eine weitere Seite gibt, einem <code>nextCursor</code>; schicke ihn als <code>cursor</code> zusammen mit <code>page</code> + 1, um die nächste Seite zu laden. <code>metatypeId</code> filtert nach Metatyp.</p>`,9)])}var u=r(c,[[`render`,l]]);export{s as __pageData,u as default};